{"id":"089768a9-5574-4b3f-94d9-e529b07dfa7e","inserted_at":"2026-07-03T22:48:50.252661+00:00","updated_at":"2026-07-03T22:48:50.252661+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- Aggiorna la funzione della Traccia Impegno con i permessi di sistema\r\nCREATE OR REPLACE FUNCTION award_action_badges()\r\nRETURNS TRIGGER \r\nSECURITY DEFINER -- <== QUESTA È LA PAROLA MAGICA\r\nAS $$\r\nDECLARE\r\n    total_reports INT;\r\n    badge_to_award TEXT;\r\n    bonus_points INT;\r\nBEGIN\r\n    SELECT COUNT(*) INTO total_reports \r\n    FROM civic_reports \r\n    WHERE user_id = NEW.user_id;\r\n\r\n    badge_to_award := NULL;\r\n    bonus_points := 0;\r\n\r\n    IF total_reports = 1 THEN\r\n        badge_to_award := 'sentinella';\r\n        bonus_points := 50;\r\n    ELSIF total_reports = 5 THEN\r\n        badge_to_award := 'esploratore';\r\n        bonus_points := 100;\r\n    ELSIF total_reports = 10 THEN\r\n        badge_to_award := 'attivo';\r\n        bonus_points := 200;\r\n    ELSIF total_reports = 25 THEN\r\n        badge_to_award := 'faro';\r\n        bonus_points := 500;\r\n    ELSIF total_reports = 50 THEN\r\n        badge_to_award := 'custode';\r\n        bonus_points := 1000;\r\n    END IF;\r\n\r\n    IF badge_to_award IS NOT NULL THEN\r\n        BEGIN\r\n            INSERT INTO user_badges (user_id, badge_type) \r\n            VALUES (NEW.user_id, badge_to_award);\r\n            \r\n            UPDATE profiles \r\n            SET total_tokens = COALESCE(total_tokens, 0) + bonus_points \r\n            WHERE id = NEW.user_id;\r\n        EXCEPTION WHEN unique_violation THEN\r\n            -- L'utente ha già questo badge, non facciamo nulla\r\n        END;\r\n    END IF;\r\n\r\n    RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\n\r\n-- Aggiorna anche la funzione della Traccia Impatto\r\nCREATE OR REPLACE FUNCTION award_impact_badges()\r\nRETURNS TRIGGER \r\nSECURITY DEFINER -- <== E ANCHE QUI\r\nAS $$\r\nDECLARE\r\n    total_confirmed INT;\r\n    total_resolved INT;\r\n    badge_to_award TEXT;\r\n    bonus_points INT;\r\nBEGIN\r\n    IF NEW.status = OLD.status OR NEW.status NOT IN ('confirmed', 'verified', 'resolved') THEN\r\n        RETURN NEW;\r\n    END IF;\r\n\r\n    badge_to_award := NULL;\r\n    bonus_points := 0;\r\n\r\n    SELECT COUNT(*) INTO total_confirmed \r\n    FROM civic_reports \r\n    WHERE user_id = NEW.user_id AND status IN ('confirmed', 'verified', 'resolved');\r\n    \r\n    SELECT COUNT(*) INTO total_resolved \r\n    FROM civic_reports \r\n    WHERE user_id = NEW.user_id AND status = 'resolved';\r\n\r\n    IF total_confirmed = 1 AND NEW.status = 'confirmed' THEN\r\n        badge_to_award := 'eco';\r\n        bonus_points := 25;\r\n    END IF;\r\n\r\n    IF total_resolved = 1 AND NEW.status = 'resolved' THEN\r\n        badge_to_award := 'forgiatore';\r\n        bonus_points := 100;\r\n    ELSIF total_resolved = 5 AND NEW.status = 'resolved' THEN\r\n        badge_to_award := 'eroe';\r\n        bonus_points := 500;\r\n    END IF;\r\n\r\n    IF badge_to_award IS NOT NULL THEN\r\n        BEGIN\r\n            INSERT INTO user_badges (user_id, badge_type) \r\n            VALUES (NEW.user_id, badge_to_award);\r\n            \r\n            UPDATE profiles \r\n            SET total_tokens = COALESCE(total_tokens, 0) + bonus_points \r\n            WHERE id = NEW.user_id;\r\n        EXCEPTION WHEN unique_violation THEN\r\n            -- Già posseduto\r\n        END;\r\n    END IF;\r\n\r\n    RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;","content_id":"089768a9-5574-4b3f-94d9-e529b07dfa7e","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
